public class JReverseNumber {
	public static void main(String[] args) {
		//Khatwa 1: Ta'reef al-mutaghayyirat alati nahtajuha li hadha al-barnamaj
		int num = 1234;
		int lastDigit;
		int reverse = 0;
		//Khatwa 2: 'Aks arqam al-'adad al-sahih bi-tariqa riyadiyya
		do {
			//Khatwa 2.1: Istikhraj al-raqm al-akhir fi al-'adad
			lastDigit = num % 10;
			//Khatwa 2.2: Ilhaaq al-raqm al-akhir ila reverse
			reverse = (reverse * 10) + lastDigit;
			//Khatwa 2.3: Izalat al-raqm al-akhir min al-'adad
			num = num / 10;
			System.out.println("al-raqm al-akhir: "+lastDigit+", al-maakoos: "+reverse+", al-'adad: "+num);
		} while (num > 0);
		System.out.println("al-'adad al-maakoos huwa " + reverse);
	}
}
